using System.Text.Json.Serialization;
using Nethereum.ABI.FunctionEncoding.Attributes;
using Nethereum.Contracts;

namespace EchoProject.Infrastructure.Blockchain.Contracts
{
    public class EchoEscrowDeployment : ContractDeploymentMessage
    {
        public EchoEscrowDeployment() : base(BYTECODE) { }
        public EchoEscrowDeployment(string bytecode) : base(bytecode) { }

        [Parameter("address", "_platformAdmin", 1)]
        public string PlatformAdmin { get; set; }
        [JsonIgnore]
        public const string BYTECODE = ""; 
    }
}